function followFocusedTabLinkOnArrow(event) {
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  const list = event.currentTarget;
  const before = list.ownerDocument.activeElement;
  requestAnimationFrame(() => {
    const next = list.ownerDocument.activeElement;
    if (next !== before && next instanceof HTMLAnchorElement && list.contains(next)) {
      next.click(); // Follow the already-rendered Link after Ariakit moves focus.
    }
  });
}
